import { relative, sep, basename } from 'path';

/**
 * Directory names (matched as whole path segments, relative to the scan root)
 * whose contents are never production app code.
 */
const NON_PRODUCTION_SEGMENTS = new Set([
  'node_modules',
  '__tests__',
  '__mocks__',
  '__fixtures__',
  '__snapshots__',
  'test',
  'tests',
  'e2e',
  'fixtures',
  'mocks',
  'mock',
  'stories',
  '.storybook',
  'storybook',
  'vendor',
  'coverage',
  '.git',
  '.expo',
  // build output and dependency folders
  'dist',
  'build',
  'pods',
  '.gradle',
  // iOS / native build output and vendored dependencies
  'deriveddata',
  'carthage',
]);

/** Directory segments that only hold development tooling (not scanned for code rules). */
const DEV_ONLY_SEGMENTS = new Set(['debug', 'debugoptimized', '__debug__']);

/** Android source sets that never ship in release builds (RN/Expo templates put cleartext traffic there). */
const ANDROID_DEBUG_SOURCE_SET = /(^|\/)src\/(debug|debugOptimized)\//i;
/** Android unit / instrumentation test source sets */
const ANDROID_TEST_SOURCE_SET = /(^|\/)src\/(test|androidTest|testDebug|testRelease)\//i;
const NATIVE_SOURCE_FILE = /\.(java|kt|swift|mm?)$/;
const NATIVE_TEST_FILE = /(Test\.(java|kt)|Tests\.(swift|mm?))$/;
/** Xcode test targets (`MyAppTests/`, `MyAppUITests/`), also vendored `.framework` bundles */
const IOS_TEST_OR_FRAMEWORK_DIR = /(.Tests|UITests|\.framework|\.xcframework)$/;

const NON_PRODUCTION_FILE_PATTERNS: RegExp[] = [
  /\.(test|spec|e2e|stories|story)\.[cm]?[jt]sx?$/i,
  /\.(mock|mocks)\.[cm]?[jt]sx?$/i,
  /^jest[.-]?(setup|config)/i,
  /^setup-?tests?\./i,
  /^(babel|metro|jest|detox)\.config\./i,
];

/**
 * Path relative to the scan root, using forward slashes. Falls back to the
 * absolute path (normalised) when the file lives outside the root.
 */
export function toRelativePath(filePath: string, rootDir?: string): string {
  const rel = rootDir ? relative(rootDir, filePath) : filePath;
  const usable = rel.startsWith('..') ? filePath : rel;
  return usable.split(sep).join('/');
}

const NON_APP_SEGMENTS = new Set([
  'scripts', 'script', 'detox', 'e2e', 'tools', 'tooling', 'ci', '.github', 'fastlane', '.circleci',
  '__tests__', '__mocks__', 'test', 'tests',
]);
const ROOT_CONFIG_FILE =
  /^(?:.+\.config\.(?:js|ts|cjs|mjs)|babel\.config\.[\w.]+|metro\.config\.[\w.]+|jest\..+|webpack\..+|\.babelrc(?:\.\w+)?)$/;

/**
 * True for files that never ship in the app binary: tooling / CI / e2e folders (any path segment relative to
 * `rootDir`) and root-level config files (`*.config.js`, `babel.config.*`, `metro.config.*`, `jest.*`, `webpack.*`).
 * A signal only: these files are still walked, rules opt in to skipping them.
 */
export function isNonAppSourcePath(filePath: string, rootDir?: string): boolean {
  const rel = toRelativePath(filePath, rootDir);
  const segments = rel.split('/');
  if (segments.slice(0, -1).some(s => NON_APP_SEGMENTS.has(s.toLowerCase()))) return true;
  return segments.length === 1 && ROOT_CONFIG_FILE.test(segments[0]);
}

const GENERATED_BUNDLE_PATH = /(?:\.bundle\.js|\.min\.js|Bundle\.js)$|(?:^|\/)res\/raw\/[^/]+\.js$/;
const BUNDLE_BANNER = /webpackBootstrap|__webpack_require__|__d\(function\s*\(|Generated by (?:browserify|webpack|rollup)|\/\*! For license information/;

/** Minified / generated JS by path (`*.min.js`, `*.bundle.js`, `*Bundle.js`, `res/raw/*.js`). */
export function isGeneratedBundlePath(filePath: string): boolean {
  return GENERATED_BUNDLE_PATH.test(filePath.split(sep).join('/'));
}

/** Minified / generated JS by content: a line over 2000 characters, or a webpack / metro bundle banner near the top. */
export function isGeneratedBundleContent(content: string): boolean {
  if (BUNDLE_BANNER.test(content.slice(0, 4096))) return true;
  let start = 0;
  while (start < content.length) {
    let end = content.indexOf('\n', start);
    if (end === -1) end = content.length;
    if (end - start > 2000) return true;
    start = end + 1;
  }
  return false;
}

/** True when the file lives in an Android `src/debug` or `src/debugOptimized` source set (any module). */
export function isAndroidDebugSourceSet(filePath: string, rootDir?: string): boolean {
  return ANDROID_DEBUG_SOURCE_SET.test(toRelativePath(filePath, rootDir));
}

/**
 * True when the file is test, mock, fixture, vendored or other non-shipping code.
 * Matches whole path segments of the path relative to `rootDir`, so a project
 * that happens to live under e.g. `/Users/me/dev/assets/app` is not affected.
 */
export function isNonProductionPath(filePath: string, rootDir?: string): boolean {
  const rel = toRelativePath(filePath, rootDir);
  const segments = rel.split('/');
  const fileName = basename(rel);

  const dirSegments = segments.slice(0, -1).map(s => s.toLowerCase());
  if (dirSegments.some(s => NON_PRODUCTION_SEGMENTS.has(s) || DEV_ONLY_SEGMENTS.has(s))) {
    return true;
  }
  if (ANDROID_DEBUG_SOURCE_SET.test(rel) || ANDROID_TEST_SOURCE_SET.test(rel)) return true;
  // iOS test targets and prebuilt frameworks hold native sources and plists, not app code
  if (/\.(java|kt|swift|mm?|plist|entitlements)$/.test(fileName) && segments.slice(0, -1).some(s => IOS_TEST_OR_FRAMEWORK_DIR.test(s))) {
    return true;
  }
  if (NATIVE_SOURCE_FILE.test(fileName) && NATIVE_TEST_FILE.test(fileName)) return true;
  const lowerRel = rel.toLowerCase();
  if (lowerRel.includes('/ios/build/') || lowerRel.startsWith('ios/build/')) {
    return true;
  }
  // Prebuilt web assets and JS bundles copied into the native projects are not first-party source
  if (/(^|\/)android\/app\/src\/[^/]+\/assets\//.test(lowerRel)) {
    return true;
  }
  return NON_PRODUCTION_FILE_PATTERNS.some(p => p.test(fileName));
}

/**
 * Convert a glob (`**`, `*`, `?`) to a RegExp that matches a relative path.
 * A leading `**\/` also matches zero directories, and a pattern without any
 * slash is matched against every path segment (like .gitignore entries).
 */
export function globToRegExp(glob: string): RegExp {
  let pattern = glob.replace(/^\.\//, '').replace(/\/+$/, '/**');
  if (!pattern.includes('/')) pattern = `**/${pattern}`;

  let re = '';
  let braceDepth = 0;
  for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i];
    if (ch === '*') {
      if (pattern[i + 1] === '*') {
        i++;
        if (pattern[i + 1] === '/') {
          i++;
          re += '(?:.*/)?';
        } else {
          re += '.*';
        }
      } else {
        re += '[^/]*';
      }
    } else if (ch === '?') {
      re += '[^/]';
    } else if (ch === '{') {
      braceDepth++;
      re += '(?:';
    } else if (ch === '}' && braceDepth > 0) {
      braceDepth--;
      re += ')';
    } else if (ch === ',' && braceDepth > 0) {
      re += '|';
    } else {
      re += ch.replace(/[.+^${}()|[\]\\]/g, '\\$&');
    }
  }
  return new RegExp(`^${re}(?:/.*)?$`);
}

/** True when the relative path matches any of the user-configured exclude globs. */
export function matchesExcludeGlobs(filePath: string, globs: string[], rootDir?: string): boolean {
  if (globs.length === 0) return false;
  const rel = toRelativePath(filePath, rootDir);
  return globs.some(g => globToRegExp(g).test(rel));
}
